<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {api,post,download,stamp} from '../api'
const props=defineProps<{catalog:any}>(),filter=ref<any>({workOrderId:'',batchId:''}),kind=ref('products'),rows=ref<any[]>([]),jobs=ref<any[]>([]),total=ref(0),batches=computed(()=>props.catalog.batches.filter((b:any)=>b.workOrderId===filter.value.workOrderId));let timer:ReturnType<typeof setInterval>
function clean(){return Object.fromEntries(Object.entries(filter.value).map(([k,v])=>[k,v||null]))}
async function search(){try{const r=await post('/api/reports/search',clean());rows.value=r.items;total.value=r.total}catch(e:any){ElMessage.error(e.message)}}
async function load(){jobs.value=await api('/api/exports')}
async function submit(){try{await post('/api/exports',{kind:kind.value,filter:clean()});await load();ElMessage.success('导出任务已提交，按当前工单、批次及筛选条件生成')}catch(e:any){ElMessage.error(e.message)}}
onMounted(()=>{load();timer=setInterval(load,4000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="panel"><div class="filters"><el-select v-model="filter.workOrderId" placeholder="必选具体工单" @change="filter.batchId='' ;rows=[]"><el-option v-for="o in catalog.orders" :key="o.id" :value="o.id" :label="o.code"/></el-select><el-select v-model="filter.batchId" placeholder="必选具体批次"><el-option v-for="b in batches" :key="b.id" :value="b.id" :label="b.code"/></el-select><el-input v-for="(label,k) in {mainCode:'主码',cellCode:'电芯码',snCode:'SN',packCode:'包装码'}" :key="k" v-model="filter[k]" :placeholder="label" clearable/><el-select v-model="filter.verdict" clearable placeholder="测试结果"><el-option label="PASS" value="PASS"/><el-option label="FAIL" value="FAIL"/></el-select><el-button type="primary" :disabled="!filter.batchId" @click="search">查询</el-button></div><p class="sub">找到 {{total}} 件，页面最多预览 200 件。测试结果筛选匹配历史结果；测试导出保留所选产品全部 FAIL、PASS、复测及详细参数。</p><el-table :data="rows"><el-table-column v-for="(label,k) in {mainCode:'主码',cellCode:'电芯码',snCode:'SN',packCode:'包装码',createdAt:'建立时间'}" :key="k" :prop="k" :label="label"/></el-table><div class="actions"><el-select v-model="kind"><el-option label="产品明细" value="products"/><el-option label="过站明细" value="passages"/><el-option label="全部测试及参数" value="tests"/></el-select><el-button :disabled="!filter.batchId" @click="submit">按当前筛选提交后台导出</el-button></div></section><section class="panel"><h2>导出任务</h2><el-table :data="jobs"><el-table-column prop="kind" label="类型"/><el-table-column prop="batchId" label="批次 ID"/><el-table-column prop="status" label="状态"/><el-table-column prop="error" label="失败原因"/><el-table-column label="创建时间"><template #default="{row}">{{stamp(row.at)}}</template></el-table-column><el-table-column label="范围"><template #default="{row}"><el-popover trigger="click" width="420"><pre>{{row.filter}}</pre><template #reference><el-button link>查看筛选</el-button></template></el-popover></template></el-table-column><el-table-column label="文件"><template #default="{row}"><el-button :disabled="row.status!=='Completed'" @click="download('/api/exports/'+row.id+'/download',row.kind+'.csv')">下载</el-button></template></el-table-column></el-table></section></template>
